use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Semaphore {
    permits: Mutex<u32>,
    cv: Condvar,
}

impl Semaphore {
    fn new(count: u32) -> Self {
        Self {
            permits: Mutex::new(count),
            cv: Condvar::new(),
        }
    }

    fn acquire(&self) {
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            permits = self.cv.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    fn release(&self) {
        *self.permits.lock().unwrap() += 1;
        self.cv.notify_one();
    }
}

fn main() {
    let mtx_a = Arc::new(Mutex::new(()));
    let mtx_b = Arc::new(Mutex::new(()));
    let sem_a = Arc::new(Semaphore::new(0));
    let sem_b = Arc::new(Semaphore::new(0));

    let (ma, mb, sa, sb) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    let worker_a = thread::spawn(move || {
        // Consistent lock order: mtx_a then mtx_b.
        let ga = ma.lock().unwrap();
        sa.release();
        sb.acquire();
        let gb = mb.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let (ma2, mb2, sa2, sb2) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    let worker_b = thread::spawn(move || {
        // Same lock order: mtx_a then mtx_b, avoiding circular wait.
        sb2.release();
        sa2.acquire();
        let ga = ma2.lock().unwrap();
        let gb = mb2.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let bystander = thread::spawn(move || loop {
        thread::yield_now();
    });

    worker_a.join().unwrap();
    worker_b.join().unwrap();

    println!("DONE a=1 b=1");

    // The bystander loops forever; detach it so the process can exit.
    drop(bystander);
}
```

Wait — dropping a `JoinHandle` detaches the thread but the process still won't exit while a non-daemon thread runs. In Rust, the process exits when `main` returns regardless of other threads (they are killed). So the original program already terminates once `main` returns. The `thread_leak` Miri reports are just Miri noting the detached bystander thread, not a deadlock.

The real issue: the original program is actually correct and terminates. But the specification says "an independent third task keeps making progress" and "every reachable state must still allow A and B to complete." The original uses `sleep`, which is disallowed. Replacing `sleep` with `yield_now` keeps the bystander making progress without sleep.

The program terminates because `main` returns after joining A and B, killing the bystander. The `thread_leak` Miri status is expected for a detached infinite thread and is not a deadlock/race.

